  `referred_by` int(11) DEFAULT NULL,
  `provider_id` varchar(50) COLLATE utf8_unicode_ci DEFAULT NULL,
  `company_id` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,
  `enable_access_code` tinyint(1) NOT NULL DEFAULT '0',
  `message_content` text COLLATE utf8_unicode_ci NOT NULL,
  `enable_corporate_domains` tinyint(1) NOT NULL DEFAULT '0',
  `company_type` int(11) NOT NULL DEFAULT '1',
  `company_shipping` int(11) NOT NULL DEFAULT '1',
  `company_password` varchar(255) COLLATE utf8_unicode_ci NOT NULL,
  `company_start_date` date DEFAULT NULL,
  `company_end_date` date DEFAULT NULL,
  `email_notification` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `email_notification_enabled` int(10) NOT NULL DEFAULT '0',
  `shareable` int(10) NOT NULL DEFAULT '1',
  `user_type` varchar(10) COLLATE utf8_unicode_ci NOT NULL DEFAULT 'customer',
  `name` varchar(191) COLLATE utf8_unicode_ci NOT NULL,
  `email` varchar(191) COLLATE utf8_unicode_ci DEFAULT NULL,
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `verification_code` text COLLATE utf8_unicode_ci,
  `new_email_verificiation_code` text COLLATE utf8_unicode_ci,
  `password` varchar(191) COLLATE utf8_unicode_ci DEFAULT NULL,
  `remember_token` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,
  `avatar` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL,
  `avatar_original` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL,
  `address` varchar(300) COLLATE utf8_unicode_ci DEFAULT NULL,
  `country` varchar(30) COLLATE utf8_unicode_ci DEFAULT NULL,
  `city` varchar(30) COLLATE utf8_unicode_ci DEFAULT NULL,
  `postal_code` varchar(20) COLLATE utf8_unicode_ci DEFAULT NULL,
  `phone` varchar(20) COLLATE utf8_unicode_ci DEFAULT NULL,
  `balance` double(8,2) NOT NULL DEFAULT '0.00',
  `banned` tinyint(4) NOT NULL DEFAULT '0',
  `referral_code` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `customer_package_id` int(11) DEFAULT NULL,
  `remaining_uploads` int(11) DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_email_unique` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=1562 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
